import { useState, useEffect, FormEvent } from 'react';
import { motion } from 'framer-motion';
import { FaWhatsapp, FaPaperPlane } from 'react-icons/fa';

interface FormField {
  name: string;
  label: string;
  type: 'text' | 'email' | 'tel' | 'textarea' | 'select';
  required?: boolean;
  options?: string[];
  placeholder?: string;
}

interface WhatsAppFormProps {
  title: string;
  description: string;
  fields: FormField[];
  messageTemplate: (data: Record<string, string>) => string;
  phoneNumber: string;
  submitButtonText?: string;
  defaultValues?: Record<string, string>;
}

export default function WhatsAppForm({
  title,
  description,
  fields,
  messageTemplate,
  phoneNumber,
  submitButtonText = 'Send via WhatsApp',
  defaultValues = {},
}: WhatsAppFormProps) {
  const [formData, setFormData] = useState<Record<string, string>>(defaultValues);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (defaultValues && Object.keys(defaultValues).length > 0) {
      setFormData((prev) => {
        const updated = { ...prev };
        Object.entries(defaultValues).forEach(([key, value]) => {
          if (!prev[key] || prev[key] === '') {
            updated[key] = value;
          }
        });
        return updated;
      });
    }
  }, [defaultValues]);

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const message = messageTemplate(formData);
    const encodedMessage = encodeURIComponent(message);
    const whatsappUrl = `https://wa.me/${phoneNumber}?text=${encodedMessage}`;

    window.open(whatsappUrl, '_blank');

    setTimeout(() => {
      setIsSubmitting(false);
      setFormData({});
    }, 1000);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8 }}
      className="max-w-3xl mx-auto"
    >
      <div className="bg-white rounded-2xl shadow-2xl p-8 md:p-12">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-gradient-to-br from-green-500 to-emerald-500 rounded-2xl mb-4">
            <FaWhatsapp className="w-8 h-8 text-white" />
          </div>
          <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">{title}</h2>
          <p className="text-lg text-gray-600">{description}</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {fields.map((field) => (
            <div key={field.name}>
              <label
                htmlFor={field.name}
                className="block text-sm font-semibold text-gray-700 mb-2"
              >
                {field.label}
                {field.required && <span className="text-red-500 ml-1">*</span>}
              </label>

              {field.type === 'textarea' ? (
                <textarea
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  onChange={handleChange}
                  required={field.required}
                  placeholder={field.placeholder}
                  rows={4}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                />
              ) : field.type === 'select' ? (
                <select
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  onChange={handleChange}
                  required={field.required}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                >
                  <option value="">Select {field.label}</option>
                  {field.options?.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  type={field.type}
                  id={field.name}
                  name={field.name}
                  value={formData[field.name] || ''}
                  onChange={handleChange}
                  required={field.required}
                  placeholder={field.placeholder}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200"
                />
              )}
            </div>
          ))}

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full py-4 px-6 bg-gradient-to-r from-green-500 to-emerald-500 text-white rounded-lg font-semibold shadow-lg hover:shadow-xl transform hover:scale-105 transition-all duration-300 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSubmitting ? (
              <>
                <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-3"></div>
                Redirecting...
              </>
            ) : (
              <>
                <FaPaperPlane className="mr-3" />
                {submitButtonText}
              </>
            )}
          </button>

          <p className="text-sm text-gray-500 text-center mt-4">
            Your message will open in WhatsApp. Make sure WhatsApp is installed on your device.
          </p>
        </form>
      </div>

      <div className="mt-8 p-6 bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl">
        <div className="flex items-start space-x-4">
          <FaWhatsapp className="w-6 h-6 text-green-600 flex-shrink-0 mt-1" />
          <div>
            <h3 className="font-semibold text-gray-900 mb-2">Why WhatsApp?</h3>
            <ul className="text-sm text-gray-600 space-y-1">
              <li>✓ Instant response from our team</li>
              <li>✓ Secure and direct communication</li>
              <li>✓ Quick follow-up and support</li>
              <li>✓ Share additional documents easily</li>
            </ul>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

components/CostCalculator.tsx.content:
import { useState } from 'react';
import { FaCalculator, FaRupeeSign } from 'react-icons/fa';

interface ServiceOption {
  name: string;
  basePrice: number;
  unit: string;
}

const services: Record<string, ServiceOption[]> = {
  'Job Support': [
    { name: 'Hourly Support', basePrice: 500, unit: 'per hour' },
    { name: 'Daily Support', basePrice: 3500, unit: 'per day' },
    { name: 'Weekly Support (20 hrs)', basePrice: 12000, unit: 'per week' },
    { name: 'Monthly Support (80 hrs)', basePrice: 40000, unit: 'per month' },
  ],
  'Development Services': [
    { name: 'Frontend Development', basePrice: 40000, unit: 'per project' },
    { name: 'Backend Development', basePrice: 60000, unit: 'per project' },
    { name: 'Full Stack Development', basePrice: 100000, unit: 'per project' },
    { name: 'Custom Enterprise Solution', basePrice: 250000, unit: 'per project' },
  ],
  'Training Programs': [
    { name: 'Individual Training (1 month)', basePrice: 15000, unit: 'per person' },
    { name: 'Corporate Training (Basic)', basePrice: 50000, unit: 'per batch (10-15)' },
    { name: 'Corporate Training (Advanced)', basePrice: 80000, unit: 'per batch (10-15)' },
    { name: 'White-Label Training Partnership', basePrice: 150000, unit: 'per program' },
  ],
  'Consultancy': [
    { name: 'Technical Consultation', basePrice: 2000, unit: 'per hour' },
    { name: 'Architecture Review', basePrice: 25000, unit: 'per project' },
    { name: 'Technology Audit', basePrice: 50000, unit: 'per audit' },
    { name: 'Digital Transformation Strategy', basePrice: 100000, unit: 'per engagement' },
  ],
};

export default function CostCalculator() {
  const [selectedCategory, setSelectedCategory] = useState('Job Support');
  const [selectedService, setSelectedService] = useState(services['Job Support'][0]);
  const [quantity, setQuantity] = useState(1);
  const [discount, setDiscount] = useState(0);

  const handleCategoryChange = (category: string) => {
    setSelectedCategory(category);
    setSelectedService(services[category][0]);
    setQuantity(1);
  };

  const handleServiceChange = (serviceName: string) => {
    const service = services[selectedCategory].find(s => s.name === serviceName);
    if (service) setSelectedService(service);
  };

  const subtotal = selectedService.basePrice * quantity;
  const discountAmount = (subtotal * discount) / 100;
  const total = subtotal - discountAmount;
  const gst = total * 0.18;
  const grandTotal = total + gst;

  return (
    <div className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
      <div className="flex items-center gap-3 mb-6">
        <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center">
          <FaCalculator className="w-6 h-6 text-white" />
        </div>
        <h3 className="text-2xl font-bold text-gray-900">Service Cost Calculator</h3>
      </div>

      <div className="space-y-6">
        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Service Category
          </label>
          <select
            value={selectedCategory}
            onChange={(e) => handleCategoryChange(e.target.value)}
            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-blue-600 focus:outline-none transition-colors"
          >
            {Object.keys(services).map((category) => (
              <option key={category} value={category}>
                {category}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Select Service
          </label>
          <select
            value={selectedService.name}
            onChange={(e) => handleServiceChange(e.target.value)}
            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-blue-600 focus:outline-none transition-colors"
          >
            {services[selectedCategory].map((service) => (
              <option key={service.name} value={service.name}>
                {service.name} - ₹{service.basePrice.toLocaleString('en-IN')} {service.unit}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Quantity / Duration
          </label>
          <input
            type="number"
            min="1"
            value={quantity}
            onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-blue-600 focus:outline-none transition-colors"
          />
        </div>

        <div>
          <label className="block text-sm font-semibold text-gray-700 mb-2">
            Discount (%)
          </label>
          <input
            type="number"
            min="0"
            max="50"
            value={discount}
            onChange={(e) => setDiscount(Math.min(50, Math.max(0, parseInt(e.target.value) || 0)))}
            className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-blue-600 focus:outline-none transition-colors"
          />
        </div>

        <div className="border-t-2 border-gray-200 pt-6 space-y-3">
          <div className="flex justify-between text-gray-700">
            <span>Subtotal:</span>
            <span className="font-semibold">₹{subtotal.toLocaleString('en-IN')}</span>
          </div>
          {discount > 0 && (
            <div className="flex justify-between text-green-600">
              <span>Discount ({discount}%):</span>
              <span className="font-semibold">-₹{discountAmount.toLocaleString('en-IN')}</span>
            </div>
          )}
          <div className="flex justify-between text-gray-700">
            <span>GST (18%):</span>
            <span className="font-semibold">₹{gst.toLocaleString('en-IN')}</span>
          </div>
          <div className="flex justify-between text-xl font-bold text-blue-600 pt-3 border-t-2 border-gray-200">
            <span>Total Amount:</span>
            <span className="flex items-center">
              <FaRupeeSign className="w-5 h-5" />
              {grandTotal.toLocaleString('en-IN')}
            </span>
          </div>
        </div>

        <p className="text-sm text-gray-500 italic text-center">
          *Prices in INR. American standard quality at Indian prices. Contact us for custom quotes.
        </p>
      </div>
    </div>
  );
}

